fn fillFlatRow(dst: []Value, column_values: []const []Value, output_indices: []const usize, row: usize) void {
    for (output_indices, dst) |col_idx, *d| {
        const col = column_values[col_idx];
        d.* = if (row < col.len) col[row] else .{ .null_val = {} };
    }
}

