    fn freeColumnValues(self: *Self, column_values: [][]Value) void {
        for (column_values) |vals| {
            for (vals) |v| v.deinit(self.allocator);
            if (vals.len > 0) self.allocator.free(vals);
        }
        self.allocator.free(column_values);
